const conv = ($('get_data').first().json.conversation || '').toString().toLowerCase().trim();
const btn = ($('get_data').first().json.btn_data || '').toString().toLowerCase().trim();
const raw = conv || btn;

const opcoes = {
  '1': 'suporte', 'btn1': 'suporte', 'suporte': 'suporte',
  '2': 'financeiro', 'btn2': 'financeiro', 'financeiro': 'financeiro',
  'financeiro e com': 'financeiro', 'financeiro e com.': 'financeiro',
  '3': 'agrotech', 'btn3': 'agrotech', 'agrotech': 'agrotech'
};

const opcao = opcoes[raw] || 'erro';

return [{ json: { rota: opcao, departamento: opcao === 'erro' ? '' : opcao } }];

const conv = ($('get_data').first().json.conversation || '').toString().toLowerCase().trim();
const btn = ($('get_data').first().json.btn_data || '').toString().toLowerCase().trim();
const raw = conv || btn;

const opcoes = {
  '1': 'fiscal', 'btn1': 'fiscal', 'fiscal': 'fiscal',
  '2': 'financeiro', 'btn2': 'financeiro', 'financeiro': 'financeiro',
  '3': 'operacional', 'btn3': 'operacional', 'operacional': 'operacional'
};

const opcao = opcoes[raw] || 'erro';

return [{ json: { rota: opcao, departamento: opcao === 'erro' ? '' : `suporte_${opcao}` } }];

const DEPTO_PARA_FILA = {
  financeiro: 2,
  agrotech: 4,
  suporte_fiscal: 6,
  suporte_financeiro: 2,
  suporte_operacional: 8,
};

const DEPTO_PREFERIDOS = {
  suporte_fiscal: [9, 7],
  suporte_financeiro: [4, 5],
  financeiro: [4, 5],
  suporte_operacional: [10, 5],
  agrotech: [],
};

const FILA_FALLBACK_ID = 1;
const FILA_FALLBACK_NOME = 'Suporte';

let departamento = '';
try { departamento = $('parse_menu_principal').first().json.departamento || ''; } catch (e) {}
if (!departamento) {
  try { departamento = $('parse_menu_suporte').first().json.departamento || ''; } catch (e) {}
}

const apiResp = $input.first().json;
const usuarios = apiResp.data || apiResp.body?.data || [];
const filasCatalogo = {};
const usuariosPorId = {};

for (const usuario of usuarios) {
  if (usuario.profile === 'admin') continue;

  usuariosPorId[usuario.id] = {
    userId: usuario.id,
    name: usuario.name,
    email: usuario.email,
    isOnline: usuario.isOnline === true,
  };

  if (!usuario?.queues?.length) continue;

  for (const fila of usuario.queues) {
    const queueId = fila.id;
    if (!filasCatalogo[queueId]) {
      filasCatalogo[queueId] = { queueId, queueName: fila.queue, usuarios: [] };
    }
    filasCatalogo[queueId].usuarios.push({
      userId: usuario.id,
      name: usuario.name,
      email: usuario.email,
      isOnline: usuario.isOnline === true,
    });
  }
}

function escolherAtendente(queueId, preferidosIds = []) {
  const fila = filasCatalogo[queueId];
  const onlineNaFila = (fila?.usuarios || []).filter((u) => u.isOnline);

  for (const prefId of preferidosIds) {
    const preferido = usuariosPorId[prefId];
    if (preferido?.isOnline) {
      return { atendente: preferido, modo: 'preferido' };
    }
  }

  const proximo = onlineNaFila.find((u) => !preferidosIds.includes(u.userId));
  if (proximo) return { atendente: proximo, modo: 'proximo_online' };

  return { atendente: null, modo: 'somente_fila' };
}

const filas = Object.values(filasCatalogo)
  .sort((a, b) => a.queueId - b.queueId)
  .map((f) => ({
    queueId: f.queueId,
    queueName: f.queueName,
    usuarios: f.usuarios.map((u) => ({
      userId: u.userId,
      usuario: u.name,
      online: u.isOnline ? 1 : 0,
    })),
  }));

const queueId = DEPTO_PARA_FILA[departamento] || FILA_FALLBACK_ID;
const preferidos = DEPTO_PREFERIDOS[departamento] || [];
const { atendente, modo } = escolherAtendente(queueId, preferidos);
const filaDestino = filasCatalogo[queueId];
const queueName = filaDestino?.queueName || FILA_FALLBACK_NOME;
const userId = atendente?.userId ?? null;

return [{
  json: {
    departamento,
    queueId,
    queueName,
    userId,
    atendenteNome: atendente?.name || null,
    atendenteOnline: userId !== null,
    modoDistribuicao: modo,
    preferidos,
    filas,
    ticketId: $('get_data').first().json.ticketID,
  },
}];

